import type { FullSchema, SystemColumns, TableName } from '../db'
import type { ChoiceValue } from '../db/types/Choice'

/** Extracts known choice value keys from a column's type */
type ColumnChoiceKeys<C> = C extends { choices: infer Ch } ? keyof Ch & (string | number) : never

/** Gets known choice values for a specific field on a table */
type FieldChoiceKeys<T extends TableName, F> = F extends keyof FullSchema<T>
    ? ColumnChoiceKeys<FullSchema<T>[F]>
    : never

/** Accepts known values with autocomplete but allows any string */
type Suggest<T extends string | number> = T | ((string | number) & Record<never, never>)

/**
 * Defines a set of choices to add to a ServiceNow table field.
 *
 * Use this API when adding choices to a field not owned by the current app —
 * for example, a platform field like `operational_status` inherited from `cmdb_ci`.
 *
 * For choices on fields owned by the current app, prefer inline choices in the Table API instead.
 *
 * @interface
 */
export type ChoiceSet<T extends TableName, F extends keyof FullSchema<T> | SystemColumns | (string & {}) = string> = {
    /** The ServiceNow table containing the target field */
    table: T
    /** The field name on the table to add choices to */
    field: F
    /**
     * Map of choice values to their configuration.
     * Keys are the choice values stored in the database (e.g., 'pending', '100').
     * Values define the label and optional properties for each choice.
     * When the field has known choices from downloaded dependencies, autocomplete suggests them.
     *
     * To remove a choice, delete it from this map. The build automatically tracks
     * removed choices via the keys system and writes `removed_choices` to the XML payload.
     */
    choices: { [value in Suggest<FieldChoiceKeys<T, F>>]?: ChoiceValue }
}

/**
 * Creates a ChoiceSet (`sys_choice_set`) that adds choices to a table field not owned by the current app.
 *
 * By default, generates v3 XML with a `<sys_choice_set>` wrapper (destructive delete-all-then-insert),
 * which is supported on all platform versions. Set `legacyChoices: false` in `now.config.json` to generate
 * v4 XML with a `<sys_choice_v2>` wrapper (additive merge with `removed_choices` tracking) on instances
 * that support it (Brazil+, Australia P4+, Zurich P11+); older instances safely skip the record.
 *
 * @param config - The ChoiceSet configuration
 * @returns The ChoiceSet configuration
 *
 * @example
 * ```typescript
 * ChoiceSet({
 *     table: 'x_snc_scan_result',
 *     field: 'state',
 *     choices: {
 *         pending: { label: 'Pending', sequence: 0 },
 *         running: { label: 'Running', sequence: 1 },
 *     },
 * })
 * ```
 */
export function ChoiceSet<
    const T extends TableName,
    const F extends keyof FullSchema<T> | SystemColumns | (string & {}),
>(config: ChoiceSet<T, F>) {
    return config
}
